const PROFILE_TABLE = 'jhrb_settingsprofile';
const PROFILE_BASE = ['jhrb_settingsprofileid', 'jhrb_name', 'jhrb_type', 'jhrb_priority', 'jhrb_isactive', '_jhrb_user_value', '_jhrb_pilotteam_value', 'modifiedon'];
const MODE_COLUMNS = SETTINGS.map((s) => s.modeColumn);
/** Value columns as the Web API names them (lookups read through _x_value). */
const VALUE_COLUMNS = SETTINGS.map((s) => (s.kind === 'Lookup' ? `_${s.valueColumn}_value` : s.valueColumn));

function summarize(r: Row): ProfileSummary {
  let defaults = 0;
  let locked = 0;
  for (const c of MODE_COLUMNS) {
    if (r[c] === Mode.Default) defaults++;
    else if (r[c] === Mode.Locked) locked++;
  }
  return {
    id: String(r.jhrb_settingsprofileid),
    name: (r.jhrb_name as string) ?? '',
    type: r.jhrb_type as number,
    priority: (r.jhrb_priority as number | null) ?? undefined,
    active: r.jhrb_isactive !== false,
    userId: ref(r, 'jhrb_user'),
    userName: display(r, 'jhrb_user'),
    pilotTeamId: ref(r, 'jhrb_pilotteam'),
    pilotTeamName: display(r, 'jhrb_pilotteam'),
    modifiedOn: r.modifiedon as string | undefined,
    defaults,
    locked,
  };
}

/** Precedence order used by the resolver: User > Group (priority desc) > Global. */
function byPrecedence(a: ProfileSummary, b: ProfileSummary): number {
  const rank = (p: ProfileSummary) => (p.type === ProfileType.User ? 0 : p.type === ProfileType.Group ? 1 : 2);
  return rank(a) - rank(b) || (b.priority ?? 0) - (a.priority ?? 0) || a.name.localeCompare(b.name);
}

async function loadProfiles(): Promise<ProfileSummary[]> {
  const rows = await queryAll(PROFILE_TABLE, { select: PROFILE_BASE.concat(MODE_COLUMNS), filter: 'statecode eq 0' });
  return rows.map(summarize).sort(byPrecedence);
}

async function loadProfile(id: string): Promise<ProfileDetail> {
  const r = await api().retrieveRow(PROFILE_TABLE, { id, select: PROFILE_BASE.concat(MODE_COLUMNS, VALUE_COLUMNS) });
  return { ...summarize(r), row: r };
}

async function findGlobal(): Promise<ProfileDetail | undefined> {
  const rows = await queryTop(PROFILE_TABLE, { select: ['jhrb_settingsprofileid'], filter: `jhrb_type eq ${ProfileType.Global} and statecode eq 0` }, 1);
  const id = rows[0]?.jhrb_settingsprofileid as string | undefined;
  return id ? loadProfile(id) : undefined;
}

async function findUserProfile(userId: string): Promise<string | undefined> {
  const rows = await queryTop(PROFILE_TABLE, { select: ['jhrb_settingsprofileid'], filter: `jhrb_type eq ${ProfileType.User} and _jhrb_user_value eq ${userId}` }, 1);
  return rows[0]?.jhrb_settingsprofileid as string | undefined;
}

/** Value of a setting as stored on the profile row (lookups as their bare id). */
function readValue(row: Row, def: SettingDefinition): unknown {
  return def.kind === 'Lookup' ? ref(row, def.valueColumn) ?? null : row[def.valueColumn];
}

function readMode(row: Row, def: SettingDefinition): number {
  return (row[def.modeColumn] as number | undefined) ?? Mode.Inherit;
}

/** Profile columns to write for a value change. Lookups are written as `_<column>_value: "/<table>(<id>)"`. */
function valuePatch(def: SettingDefinition, value: unknown): Row {
  if (def.kind === 'Lookup') return { [`_${def.valueColumn}_value`]: link(def.target ?? 'transactioncurrency', value ? String(value) : null) };
  return { [def.valueColumn]: value === '' ? null : value };
}

function pilotTeamPatch(teamId: string | undefined): Row {
  return { _jhrb_pilotteam_value: link('team', teamId) };
}

async function updateProfile(id: string, changes: Row): Promise<void> {
  await api().updateRow(PROFILE_TABLE, id, changes);
}

async function createGroupProfile(name: string, priority: number): Promise<string> {
  return api().createRow(PROFILE_TABLE, { jhrb_name: name, jhrb_type: ProfileType.Group, jhrb_priority: priority, jhrb_isactive: true });
}

async function deleteProfile(id: string): Promise<void> {
  await api().deleteRow(PROFILE_TABLE, id);
}

interface Scope {
  id: string;
  profileId: string;
  type: number;
  teamId?: string;
  teamName?: string;
  businessUnitId?: string;
  businessUnitName?: string;
  includeChildren: boolean;
}

async function loadScopes(profileId?: string): Promise<Scope[]> {
  const rows = await queryAll('jhrb_profilescope', {
    select: ['jhrb_profilescopeid', 'jhrb_scopetype', '_jhrb_team_value', '_jhrb_businessunit_value', '_jhrb_profile_value', 'jhrb_includechildbu'],
    filter: profileId ? `_jhrb_profile_value eq ${profileId} and statecode eq 0` : 'statecode eq 0',
  });
  return rows.map((r) => ({
    id: String(r.jhrb_profilescopeid),
    profileId: ref(r, 'jhrb_profile') ?? '',
    type: r.jhrb_scopetype as number,
    teamId: ref(r, 'jhrb_team'),
    teamName: display(r, 'jhrb_team'),
    businessUnitId: ref(r, 'jhrb_businessunit'),
    businessUnitName: display(r, 'jhrb_businessunit'),
    includeChildren: r.jhrb_includechildbu === true,
  }));
}

async function addScope(profileId: string, scope: { teamId?: string; businessUnitId?: string; includeChildren?: boolean; name: string }): Promise<void> {
  const row: Row = { jhrb_name: scope.name, _jhrb_profile_value: link('jhrb_settingsprofile', profileId), jhrb_includechildbu: !!scope.includeChildren };
  if (scope.teamId) { row.jhrb_scopetype = ScopeType.Team; row._jhrb_team_value = link('team', scope.teamId); }
  else { row.jhrb_scopetype = ScopeType.BusinessUnit; row._jhrb_businessunit_value = link('businessunit', scope.businessUnitId); }
  await api().createRow('jhrb_profilescope', row);
}

async function removeScope(id: string): Promise<void> {
  await api().deleteRow('jhrb_profilescope', id);
}

function describeScopes(scopes: Scope[]): string {
  if (scopes.length === 0) return 'No scopes yet';
  return scopes.map((s) => (s.teamId ? `Team ${s.teamName ?? ''}` : `BU ${s.businessUnitName ?? ''}${s.includeChildren ? ' + child BUs' : ''}`)).join('; ');
}

// ---- shared/operations.ts
interface Job {
  id: string;
  name: string;
  status: number;
  reason?: number;
  applyMode?: number;
  scope?: number;
  dryRun: boolean;
  processed: number;
  updated: number;
  unchanged: number;
  failed: number;
  chunks: number;
  settingFilter?: string;
  userName?: string;
  profileId?: string;
  profileName?: string;
  error?: string;
  createdOn?: string;
  startedOn?: string;
  completedOn?: string;
}

const JOB_COLUMNS = ['jhrb_rolloutjobid', 'jhrb_name', 'jhrb_status', 'jhrb_reason', 'jhrb_applymode', 'jhrb_scope', 'jhrb_dryrun', 'jhrb_processed', 'jhrb_updated',
  'jhrb_unchanged', 'jhrb_failed', 'jhrb_chunks', 'jhrb_settingfilter', '_jhrb_user_value', '_jhrb_profile_value', 'jhrb_error', 'createdon', 'jhrb_startedon', 'jhrb_completedon'];

function num(v: unknown): number {
  return typeof v === 'number' ? v : 0;
}

function toJob(r: Row): Job {
  return {
    id: String(r.jhrb_rolloutjobid),
    name: (r.jhrb_name as string) ?? '',
    status: r.jhrb_status as number,
    reason: r.jhrb_reason as number | undefined,
    applyMode: r.jhrb_applymode as number | undefined,
    scope: r.jhrb_scope as number | undefined,
    dryRun: r.jhrb_dryrun === true,
    processed: num(r.jhrb_processed),
    updated: num(r.jhrb_updated),
    unchanged: num(r.jhrb_unchanged),
    failed: num(r.jhrb_failed),
    chunks: num(r.jhrb_chunks),
    settingFilter: (r.jhrb_settingfilter as string | null) ?? undefined,
    userName: display(r, 'jhrb_user'),
    profileId: ref(r, 'jhrb_profile'),
    profileName: display(r, 'jhrb_profile'),
    error: (r.jhrb_error as string | null) ?? undefined,
    createdOn: r.createdon as string | undefined,
    startedOn: (r.jhrb_startedon as string | null) ?? undefined,
    completedOn: (r.jhrb_completedon as string | null) ?? undefined,
  };
}

async function loadJobs(top = 50): Promise<Job[]> {
  return (await queryTop('jhrb_rolloutjob', { select: JOB_COLUMNS, orderBy: 'createdon desc' }, top)).map(toJob);
}

async function cancelJob(id: string): Promise<void> {
  await api().updateRow('jhrb_rolloutjob', id, { jhrb_status: JobStatus.Cancelled });
}

function isActive(j: Job): boolean {
  return j.status === JobStatus.Pending || j.status === JobStatus.Running;
}

interface LogEntry {
  id: string;
  setting?: string;
  source?: number;
  oldValue?: string;
  attempted?: string;
  applied?: string;
  userId?: string;
  userName?: string;
  profileId?: string;
  profileName?: string;
  createdOn?: string;
}

async function loadLog(opts: { top?: number; userId?: string; profileId?: string; source?: number; since?: Date } = {}): Promise<LogEntry[]> {
  const f: string[] = [];
  if (opts.userId) f.push(`_jhrb_user_value eq ${opts.userId}`);
  if (opts.profileId) f.push(`_jhrb_profile_value eq ${opts.profileId}`);
  if (opts.source) f.push(`jhrb_source eq ${opts.source}`);
  if (opts.since) f.push(`createdon ge ${opts.since.toISOString()}`);
  const rows = await queryTop('jhrb_settingslog', {
    select: ['jhrb_settingslogid', 'jhrb_setting', 'jhrb_source', 'jhrb_oldvalue', 'jhrb_attemptedvalue', 'jhrb_appliedvalue', '_jhrb_user_value', '_jhrb_profile_value', 'createdon'],
    filter: f.length ? f.join(' and ') : undefined,
    orderBy: 'createdon desc',
  }, opts.top ?? 100);
  return rows.map((r) => ({
    id: String(r.jhrb_settingslogid),
    setting: (r.jhrb_setting as string | null) ?? undefined,
    source: r.jhrb_source as number | undefined,
    oldValue: (r.jhrb_oldvalue as string | null) ?? undefined,
    attempted: (r.jhrb_attemptedvalue as string | null) ?? undefined,
    applied: (r.jhrb_appliedvalue as string | null) ?? undefined,
    userId: ref(r, 'jhrb_user'),
    userName: display(r, 'jhrb_user'),
    profileId: ref(r, 'jhrb_profile'),
    profileName: display(r, 'jhrb_profile'),
    createdOn: r.createdon as string | undefined,
  }));
}

// ---- Custom APIs ---------------------------------------------------------------------------------------------

interface ApplyResult { jobId?: string; updated: number; unchanged: number; failed: number }
type ApplyMode = 'Full' | 'LockedOnly' | 'Auto';

async function applyDefaults(args: { scope: 'All' | 'User'; userId?: string; applyMode?: ApplyMode; dryRun?: boolean; settings?: string[] }): Promise<ApplyResult> {
  const r = await callApi('jhrb_ApplyDefaults', {
    Scope: args.scope, UserId: args.userId, Setting: args.settings?.join(','), DryRun: args.dryRun, ApplyMode: args.applyMode ?? 'Full',
  });
  const jobId = r.JobId as string | undefined;
  return {
    jobId: jobId && jobId !== '00000000-0000-0000-0000-000000000000' ? jobId : undefined,
    updated: num(r.Updated),
    unchanged: num(r.Unchanged),
    failed: num(r.Failed),
  };
}

async function reconcile(): Promise<string | undefined> {
  const r = await callApi('jhrb_ReconcileSettings', {});
  return r.JobId as string | undefined;
}

interface LoadResult { profileId: string; loaded: number; keptManaged: number }

async function loadCurrentValues(args: { profileId?: string; userId?: string; overwriteManaged?: boolean }): Promise<LoadResult> {
  const r = await callApi('jhrb_LoadCurrentSettings', { ProfileId: args.profileId, UserId: args.userId, OverwriteManaged: args.overwriteManaged });
  return { profileId: String(r.ProfileId), loaded: num(r.Loaded), keptManaged: num(r.KeptManaged) };
}

interface EffectiveSetting { setting: string; label: string; value: string; mode: 'Inherit' | 'Default' | 'Locked'; source: string; sourceId: string }
interface Effective { settings: EffectiveSetting[]; layers: string[]; inScope: boolean }

async function resolveEffective(userId: string): Promise<Effective> {
  const r = await callApi('jhrb_ResolveEffectiveSettings', { UserId: userId });
  return {
    settings: JSON.parse((r.Settings as string) || '[]'),
    layers: JSON.parse((r.Layers as string) || '[]'),
    inScope: r.InScope === true,
  };
}

// ---- shared/directory.ts
interface User {
  id: string;
  fullName: string;
  title?: string;
  email?: string;
  businessUnitId?: string;
  businessUnitName?: string;
  disabled: boolean;
  licensed: boolean;
}

const USER_COLUMNS = ['systemuserid', 'fullname', 'title', 'internalemailaddress', '_businessunitid_value', 'isdisabled', 'islicensed'];
const INTERACTIVE = 'isdisabled eq false and accessmode eq 0 and applicationid eq null';

function toUser(r: Row): User {
  return {
    id: String(r.systemuserid),
    fullName: (r.fullname as string) ?? '',
    title: (r.title as string | null) ?? undefined,
    email: (r.internalemailaddress as string | null) ?? undefined,
    businessUnitId: ref(r, 'businessunitid'),
    businessUnitName: display(r, 'businessunitid'),
    disabled: r.isdisabled === true,
    licensed: r.islicensed === true,
  };
}

/** Interactive, enabled users whose name or email matches the text. */
async function searchUsers(text: string, top = 25): Promise<User[]> {
  const t = text.trim();
  const match = t ? ` and (startswith(fullname,${q(t)}) or startswith(internalemailaddress,${q(t)}) or contains(fullname,${q(t)}))` : '';
  return (await queryTop('systemuser', { select: USER_COLUMNS, filter: INTERACTIVE + match, orderBy: 'fullname asc' }, top)).map(toUser);
}

async function getUser(id: string): Promise<User> {
  return toUser(await api().retrieveRow('systemuser', { id, select: USER_COLUMNS }));
}

/** Licensed interactive users (the population a rollout can touch). The page runtime has no $count, so this pages through ids. */
async function countLicensedUsers(): Promise<number> {
  return (await queryAll('systemuser', { select: ['systemuserid'], filter: `islicensed eq true and ${INTERACTIVE}` }, 50000)).length;
}

async function countTeamMembers(teamId: string): Promise<number> {
  return (await queryAll('systemuser', { select: ['systemuserid'], filter: `isdisabled eq false and teammembership_association/any(t:t/teamid eq ${teamId})` }, 50000)).length;
}

interface Named { id: string; name: string }

async function searchTeams(text: string): Promise<Named[]> {
  const rows = await queryTop('team', { select: ['teamid', 'name'], filter: text ? `contains(name,${q(text)})` : undefined, orderBy: 'name asc' }, 25);
  return rows.map((r) => ({ id: String(r.teamid), name: String(r.name ?? '') }));
}

async function searchBusinessUnits(text: string): Promise<Named[]> {
  const rows = await queryTop('businessunit', { select: ['businessunitid', 'name'], filter: text ? `contains(name,${q(text)})` : undefined, orderBy: 'name asc' }, 25);
  return rows.map((r) => ({ id: String(r.businessunitid), name: String(r.name ?? '') }));
}

/** The user's usersettings row (managed attributes only), or undefined if it does not exist yet. */
async function getUserSettings(userId: string): Promise<Row | undefined> {
  const select = SETTINGS.map((s) => (s.kind === 'Lookup' || s.kind === 'LookupText' ? `_${s.attribute}_value` : s.attribute));
  const rows = await queryTop('usersettings', { select, filter: `systemuserid eq ${userId}` }, 1);
  return rows[0];
}

